define(['core/ajax', 'core/templates', 'core/notification'], function(Ajax, Templates, Notification) {

    var SELECTORS = {
        SEARCH_INPUT: '#lpp-search-input',
        RESULTS: '[data-region="lpp-search-results"]',
    };

    var SEARCH_DEBOUNCE_MS = 250;
    var MIN_QUERY_LENGTH = 2;

    var debounceTimer = null;

    var searchUsers = function(query) {
        return Ajax.call([{
            methodname: 'local_profilephoto_search_users',
            args: {query: query, limit: 20},
        }])[0];
    };

    var getUser = function(userid) {
        return Ajax.call([{
            methodname: 'local_profilephoto_get_user',
            args: {userid: userid},
        }])[0];
    };

    var renderResults = function(target, users) {
        return Templates.renderForPromise('local_profilephoto/search_results', {
            hasusers: users.length > 0,
            users: users,
        }).then(function(result) {
            Templates.replaceNodeContents(target, result.html, result.js);
            return null;
        });
    };

    var init = function(onSelect) {
        var input = document.querySelector(SELECTORS.SEARCH_INPUT);
        var resultsRegion = document.querySelector(SELECTORS.RESULTS);

        var clear = function() {
            resultsRegion.innerHTML = '';
            input.value = '';
        };

        input.addEventListener('input', function() {
            var query = input.value.trim();
            window.clearTimeout(debounceTimer);

            if (query.length < MIN_QUERY_LENGTH) {
                resultsRegion.innerHTML = '';
                return;
            }

            debounceTimer = window.setTimeout(function() {
                searchUsers(query).then(function(users) {
                    return renderResults(resultsRegion, users);
                }).catch(Notification.exception);
            }, SEARCH_DEBOUNCE_MS);
        });

        resultsRegion.addEventListener('click', function(event) {
            var button = event.target.closest('[data-userid]');
            if (!button) {
                return;
            }

            var userid = parseInt(button.dataset.userid, 10);
            getUser(userid).then(function(user) {
                clear();
                onSelect(user);
                return null;
            }).catch(Notification.exception);
        });

        return {
            focus: function() {
                input.focus();
            },
            clear: clear,
        };
    };

    return {init: init};
});
